import {VERSION,todayISO,localDate,addDays,daysBetween,seedState,membership,openVisit,actorFor,register,renew,attemptCheckIn,checkOut,publishNotice,cancelNotice,visibleNotices,saveHours,resolveHours,summary} from './model.mjs';

const KEY='gymflow-project-demo-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY)||'null');if(state?.version!==VERSION)state=null;}catch{}state||=seedState();
let role=sessionStorage.getItem('gymflow-role')||'staff';if(!['staff','manager','member','public'].includes(role))role='staff';
let view=['staff','manager'].includes(role)?'overview':role==='member'?'portal':'status';
let query='',memberFilter='all',attendanceTab='visits',chartDays=7,reportDays=7,currentMember=state.members[0]?.id,uploadedPhoto='',selectedCheckin='',toastTimer;
const $=s=>document.querySelector(s);
const today=()=>todayISO();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'E '+Number(n).toLocaleString('en-SZ',{minimumFractionDigits:2,maximumFractionDigits:2});
const fullname=m=>m?m.first+' '+m.last:'Unknown member';
const dateFmt=(date,opts={day:'numeric',month:'short',year:'numeric'})=>date?new Intl.DateTimeFormat('en-GB',{...opts,timeZone:'Africa/Mbabane'}).format(new Date(date.length===10?date+'T12:00:00Z':date)):'—';
const timeFmt=date=>date?dateFmt(date,{hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const initials=m=>(m?.first?.[0]||'?')+(m?.last?.[0]||'');
const staff=()=>['staff','manager'].includes(role);
const scopeName=s=>({gym:'Whole gym',weights:'Weights area',cardio:'Cardio area',studio:'Studio'}[s]||s);
const svgPaths={
  gym:'<path d="M3 9v6m3-9v12m12-12v12m3-9v6M6 12h12"/>',
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',
  visit:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 2v4m8-4v4M4 10h16m-11 5 2 2 4-4"/>',
  wallet:'<path d="M20 7H5a2 2 0 0 1 0-4h13v4m-15-2v14a2 2 0 0 0 2 2h15V7m0 5h-6v5h6m-3-2.5h.01"/>',
  notice:'<path d="m3 11 17-6v14L3 14v-3m4 4 1 6h4l-2-5M3 11H1v3h2"/>',
  chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8v-7"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12a2 2 0 0 0 4 0"/>',
  down:'<path d="m7 10 5 5 5-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  enter:'<path d="M14 3h6v18h-6M3 12h12m-5-5 5 5-5 5"/>',exit:'<path d="M10 3H4v18h6m3-14 5 5-5 5M8 12h10"/>',
  check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',
  filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4m-4 10 3 3 5-5"/>',
  settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4.2 1.9c-1.2.6-1.7 1.3-1.7 2.6m0 3h.01"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',receipt:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2V3m4 5h6m-6 4h6m-6 4h4"/>',
  leaf:'<path d="M20 3C8 2 3 8 5 15c6 6 15 1 15-12ZM5 20l10-12"/>',refresh:'<path d="M20 7V3l-3 3a8 8 0 1 0 2 10M20 3h-4"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',print:'<path d="M7 8V3h10v5M7 17H3v-7h18v7h-4M7 14h10v7H7v-7"/>',
  card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20m-15 6h3"/>',audit:'<path d="M9 3H4v18h16V3h-5m-6 0v4h6V3H9m-1 9h8m-8 4h6"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${svgPaths[name]||svgPaths.grid}</svg>`;
function avatar(m,index=0,big=false){return `<span class="avatar ${['','violet','sand','blue'][index%4]} ${big?'big':''}" aria-hidden="true">${esc(initials(m))}</span>`;}
function badge(t,color='green'){return `<span class="badge ${color}">${esc(t)}</span>`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Your browser could not save this session. Changes remain available until the page closes.');}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('toast-visible'),4200);}
function go(v){query='';view=v;render();window.scrollTo({top:0,behavior:'smooth'});}
function setRole(r){role=r;sessionStorage.setItem('gymflow-role',r);view=staff()?'overview':r==='member'?'portal':'status';query='';closeModal();render();}
const pages={overview:'Overview',members:'Members',attendance:'Attendance',payments:'Payments',notices:'Notices & hours',reports:'Reports',audit:'Activity log',portal:'My membership',status:'Gym status'};
function nav(){const items=staff()?[['overview','grid','Overview'],['members','users','Members'],['attendance','visit','Attendance'],['payments','wallet','Payments'],['notices','notice','Notices & hours'],['reports','chart','Reports']]:role==='member'?[['portal','card','My membership'],['status','notice','Gym status']]:[['status','notice','Gym status']];return items.map(([v,i,t])=>`<button class="nav-item ${view===v?'active':''}" data-action="nav" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${v==='members'?`<span class="nav-count">${state.members.length}</span>`:''}</button>`).join('');}
function render(){if(!staff()&&!['portal','status'].includes(view))view=role==='member'?'portal':'status';if(view==='audit'&&role!=='manager')view='overview';const person=role==='manager'?{first:'Lungile',last:'Dube'}:role==='member'?state.members.find(m=>m.id===currentMember):{first:'Jamie',last:'Dlamini'};const titleRole={staff:'Front desk',manager:'Manager',member:'Member',public:'Public visitor'}[role];
  $('#app').innerHTML=`<aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#" data-action="home" aria-label="Gymflow home"><span class="brand-mark">${icon('gym')}</span><span class="brand-name">gym<span>flow</span></span></a><p class="nav-label">${staff()?'WORKSPACE':'YOUR GYM'}</p><nav>${nav()}</nav><div class="sidebar-spacer"></div>${role==='manager'?`<button class="nav-item ${view==='audit'?'active':''}" data-action="nav" data-view="audit">${icon('audit')}Activity log</button>`:''}<button class="nav-item" data-action="preview">${icon('user')}Switch workspace</button><button class="nav-item" data-action="help">${icon('help')}Project guide</button><div class="side-note">${icon('leaf')}<strong>A little progress, every day.</strong><p>Less admin. More time for the people moving your gym forward.</p></div><div class="sidebar-footer"><span class="status-dot"></span>Interactive prototype · Sample data</div></aside><div class="app-shell"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-toggle" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">${staff()?'Workspace':role==='member'?'Member portal':'Public'}<span>/</span><strong>${esc(pages[view])}</strong></div></div><div class="top-actions">${staff()?`<div class="global-search">${icon('search')}<input id="global-search" data-search="global" placeholder="Search members..." aria-label="Search members" value="${esc(query)}"><kbd>⌘ K</kbd></div>`:''}<button class="icon-button" data-action="nav" data-view="${staff()?'notices':'status'}" aria-label="View notices">${icon('bell')}<span class="notification-dot"></span></button><button class="profile" data-action="preview" aria-label="Switch demo workspace">${avatar(person,0)}<span class="profile-text"><strong>${role==='public'?'Welcome, visitor':esc(fullname(person))}</strong><small>${titleRole}</small></span>${icon('down')}</button>${role==='public'?`<button class="btn small" data-action="preview">Sign in</button>`:''}</div></header><main class="main" id="main" tabindex="-1">${renderPage()}<footer class="system-footer"><span>Gym Management System <span aria-hidden="true">·</span> Software engineering project <span aria-hidden="true">·</span> Sample data</span><label class="preview-select">Preview as<select id="role-preview" aria-label="Preview interface as a different role">${[['staff','Front desk'],['manager','Manager'],['member','Member'],['public','Public visitor']].map(([r,t])=>`<option value="${r}" ${role===r?'selected':''}>${t}</option>`).join('')}</select></label></footer></main></div>`;
}
function intro(eyebrow,title,sub,actions=''){return `<section class="page-intro"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${sub}</p></div><div class="intro-actions">${actions}</div></section>`;}
function metric(title,value,sub,i,featured=false,spark=false){return `<article class="metric ${featured?'featured':''}"><div class="metric-label">${title}<span class="metric-icon">${icon(i)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom">${sub}</div>${spark?`<svg class="mini-spark" viewBox="0 0 90 30" fill="none" aria-hidden="true"><path d="M1 27 11 22 21 24 31 14 41 18 51 9 61 12 71 5 89 2" stroke="${featured?'#d5eb87':'#c2d1a8'}" stroke-width="1.6"/></svg>`:''}</article>`;}
function metricsHTML(){const x=summary(state);return `<section class="metrics" aria-label="Gym statistics">${metric('Active memberships',x.active,`<strong>${x.members} members</strong> <span>registered in total</span>`,'users',true,true)}${metric('Check-ins today',x.entries,`<strong>${new Set(state.visits.filter(v=>localDate(v.checkedIn)===today()).map(v=>v.memberId)).size} unique members</strong> <span>and counting</span>`,'visit',false,true)}${metric('Currently in the gym',x.inside,`<span class="status-dot"></span><span>Live attendance</span>`,'gym')}${metric('Expiring in 7 days',x.expiring,`<strong>Keep the momentum</strong> <span>· renewal due</span>`,'clock')}</section>`;}
function attendanceChart(days=7){const a=Array.from({length:days},(_,i)=>{const d=addDays(today(),i-days+1);return {date:d,count:state.visits.filter(v=>localDate(v.checkedIn)===d).length};});const max=Math.max(20,Math.ceil(Math.max(...a.map(x=>x.count))/5)*5),x0=29,y0=10,chartW=655,chartH=145;const px=i=>x0+i*chartW/(days-1),py=n=>y0+chartH-n/max*chartH;const points=a.map((v,i)=>`${px(i)},${py(v.count)}`).join(' ');const path=`M${x0},${y0+chartH} L${points.replace(/ /g,' L')} L${px(days-1)},${y0+chartH}Z`;return `<svg class="chart" viewBox="0 0 710 200" role="img" aria-label="Check-ins over the last ${days} days"><title>Daily attendance: ${a.map(x=>dateFmt(x.date,{day:'numeric',month:'short'})+' '+x.count+' check-ins').join('; ')}</title><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#bace9b" stop-opacity=".28"/><stop offset="100%" stop-color="#dce6c9" stop-opacity=".03"/></linearGradient></defs>${[0,1,2,3,4].map(i=>{const v=max*i/4;return `<line x1="${x0}" y1="${py(v)}" x2="${x0+chartW}" y2="${py(v)}" stroke="#edf0e7" stroke-dasharray="3 5"/><text x="17" y="${py(v)+3}" text-anchor="end">${v}</text>`;}).join('')}<path d="${path}" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#709661" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>${a.map((v,i)=>`${i%Math.ceil(days/7)===0||i===days-1?`<text x="${px(i)}" y="182" text-anchor="middle">${dateFmt(v.date,days===7?{weekday:'short'}:{day:'numeric',month:'short'})}</text>`:''}<circle cx="${px(i)}" cy="${py(v.count)}" r="3" fill="white" stroke="#709661" stroke-width="1.5"><title>${v.count} check-ins</title></circle>`).join('')}</svg>`;}
function gymState(){const h=resolveHours(state,'gym');const parts=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Africa/Mbabane'}).format(new Date());return {hours:h,open:!h.closed&&parts>=h.open&&parts<h.close,time:parts};}
function gymCard(){const {hours,open,time}=gymState();return `<section class="card gym-status"><div class="card-head"><h2>Gym status</h2><span class="open-pill"><span class="status-dot"></span>${open?'OPEN NOW':'CLOSED NOW'}</span></div><div class="gym-illustration"><svg viewBox="0 0 160 75" fill="none" aria-hidden="true"><path d="M10 66h140M19 66V39h48v27M26 39V21h30v18M76 66V30h55v36M83 30V14h41v16M33 21V9h16v12m-22 29h11v8H27m17-8h11v8H44m41-10h12v10H85m23-10h12v10h-12m-19-33h22m-11-9v18" stroke="#829b6b" stroke-width="1.5"/><circle cx="140" cy="17" r="8" fill="#e3ebd3"/><path d="M140 13v5l3 1" stroke="#829b6b" stroke-width="1.4"/></svg></div><h3 class="gym-state-title">${open?'A good day to show up.':'See you next session.'}</h3><p class="gym-state-hours">Today ${hours.closed?'· Closed':`· ${hours.open} – ${hours.close}`}</p><div class="card-body">${['weights','cardio','studio'].map(s=>{const h=resolveHours(state,s),available=!h.closed&&time>=h.open&&time<h.close;return `<div class="service-row"><span>${scopeName(s)}</span><span><span class="status-dot" style="background:${available?'#659145':'#a28a6b'}"></span>${available?'Open':'Closed'}</span></div>`;}).join('')}</div></section>`;}
function visitTable(visits,actions=true){return `<div class="table-wrap"><table><thead><tr><th scope="col">MEMBER</th><th scope="col">CHECK-IN</th><th scope="col">${view==='overview'?'MEMBERSHIP':'CHECK-OUT'}</th><th scope="col">STATUS</th>${actions?'<th scope="col"></th>':''}</tr></thead><tbody>${visits.length?visits.map((v,i)=>{const m=state.members.find(m=>m.id===v.memberId),mm=m&&membership(state,m);return `<tr><td><div class="name-cell">${avatar(m,i)}<div><strong>${esc(fullname(m))}</strong><small>${esc(m?.id)}</small></div></div></td><td>${view==='overview'?timeFmt(v.checkedIn):dateFmt(v.checkedIn,{day:'numeric',month:'short'})+' · '+timeFmt(v.checkedIn)}</td><td>${view==='overview'?esc(mm?.plan?.name||'—'):timeFmt(v.checkedOut)}</td><td>${badge(v.checkedOut?'Checked out':'In the gym',v.checkedOut?'gray':'green')}</td>${actions?`<td>${!v.checkedOut?`<button class="btn text" data-action="checkout" data-id="${esc(v.id)}" aria-label="Check out ${esc(fullname(m))}">${icon('exit')}<span>Check out</span></button>`:'<span aria-label="Visit complete">—</span>'}</td>`:''}</tr>`;}).join(''):`<tr><td colspan="${actions?5:4}" class="empty">No attendance records match this view.</td></tr>`}</tbody></table></div>`;}
function noticePreview(){const n=visibleNotices(state).sort((a,b)=>b.starts.localeCompare(a.starts)).slice(0,2);return `<section class="card notices-side"><div class="card-head"><div><h2>On the noticeboard</h2><p>A little heads-up for your day.</p></div>${icon('notice')}</div><div class="notice-preview">${n.map(n=>`<article class="notice-item"><div class="notice-meta">${badge(n.status,n.status==='Upcoming'?'orange':'purple')}<span>${esc(scopeName(n.scope))}</span></div><h3>${esc(n.message)}</h3><p>${esc(n.detail)}</p><time>${dateFmt(n.starts,{day:'numeric',month:'short'})}${n.starts===n.ends?'':' – '+dateFmt(n.ends,{day:'numeric',month:'short'})}</time></article>`).join('')||'<div class="empty">No current or upcoming notices.</div>'}</div></section>`;}
function overview(){const recent=state.visits.filter(v=>localDate(v.checkedIn)===today()).slice().reverse().slice(0,5),total=state.visits.filter(v=>localDate(v.checkedIn)>=addDays(today(),-chartDays+1)).length;return intro('A LITTLE MOMENTUM GOES A LONG WAY','Your gym, at a glance.','Good things happen when we keep moving. Here’s what’s happening today.',`<span class="date-control">${icon('visit')}${dateFmt(today(),{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</span><button class="btn" data-action="register">${icon('plus')}Register member</button><button class="btn primary" data-action="checkin">${icon('enter')}Check in member</button>`)+metricsHTML()+`<div class="content-grid"><section class="card"><div class="card-head"><div><h2>Attendance overview</h2><p>Small steps. Stronger routines.</p></div><div class="segmented" aria-label="Attendance chart period"><button data-action="chart-range" data-days="7" class="${chartDays===7?'active':''}">7 days</button><button data-action="chart-range" data-days="14" class="${chartDays===14?'active':''}">14 days</button></div></div><div class="chart-wrap">${attendanceChart(chartDays)}</div><div class="chart-footer"><span class="chart-key">Member check-ins</span><span><strong>${total}</strong> visits in the last ${chartDays} days</span></div></section>${gymCard()}</div><div class="wide-bottom"><section class="card table-card"><div class="card-head"><div><h2>Today at the front desk</h2><p>Every visit is a step in the right direction.</p></div><button class="btn text" data-action="nav" data-view="attendance">View all ${icon('arrow')}</button></div>${visitTable(recent)}<div class="table-footer"><span>Latest ${recent.length} of ${summary(state).entries} check-ins today</span><span><span class="status-dot"></span>Live demo activity</span></div></section>${noticePreview()}</div>`;}
function filteredMembers(){return state.members.filter(m=>{const x=membership(state,m);return (!query||(fullname(m)+' '+m.id+' '+m.idNumber).toLowerCase().includes(query.toLowerCase()))&&(memberFilter==='all'||memberFilter==='active'&&x.active&&m.account==='ENABLED'||memberFilter==='expired'&&!x.active||memberFilter==='suspended'&&m.account==='SUSPENDED'||memberFilter==='expiring'&&x.active&&x.days<=7);});}
function members(){const list=filteredMembers();return intro('YOUR PEOPLE, IN ONE PLACE','Members','Keep memberships moving, from the very first visit to the next renewal.',`<button class="btn" data-action="export-members">${icon('download')}Export list</button><button class="btn primary" data-action="register">${icon('plus')}Register member</button>`)+`<section class="card"><div class="toolbar"><label class="search-field">${icon('search')}<input id="member-search" data-search="members" placeholder="Search name, member no. or ID..." aria-label="Search member directory" value="${esc(query)}"></label><select class="filter-select" id="member-filter" aria-label="Filter member status">${[['all','All members'],['active','Active'],['expiring','Expiring soon'],['expired','Expired'],['suspended','Suspended']].map(([v,t])=>`<option value="${v}" ${memberFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th scope="col">MEMBER</th><th scope="col">PLAN</th><th scope="col">EXPIRY DATE</th><th scope="col">MEMBERSHIP</th><th scope="col">ACCOUNT</th><th scope="col">ACTIONS</th></tr></thead><tbody>${list.map((m,i)=>{const x=membership(state,m);return `<tr><td><div class="name-cell">${avatar(m,i)}<div><strong>${esc(fullname(m))}</strong><small>${esc(m.id)}</small></div></div></td><td>${esc(x.plan?.name||'No plan')}</td><td>${dateFmt(x.expiry)}</td><td>${badge(x.active?x.days<=7?x.days+' days left':'Active':'Expired',x.active?x.days<=7?'orange':'green':'red')}</td><td>${badge(m.account==='ENABLED'?'Enabled':'Suspended',m.account==='ENABLED'?'gray':'red')}</td><td><button class="btn text" data-action="member" data-id="${esc(m.id)}">View</button><button class="btn text" data-action="renew" data-id="${esc(m.id)}">Renew ${icon('arrow')}</button></td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">No members found. Try another name or status filter.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${list.length} of ${state.members.length} members</span><span>Membership and account status are tracked separately</span></div></section>`;}
function attendance(){const visits=state.visits.slice().reverse();return intro('EVERY VISIT COUNTS','Attendance','Confirm identities, record entry and keep track of who is still in the gym.',`<button class="btn primary" data-action="checkin">${icon('enter')}Check in member</button>`)+metricsHTML()+`<section class="card"><div class="toolbar"><div class="tab-buttons"><button class="${attendanceTab==='visits'?'active':''}" data-action="attendance-tab" data-tab="visits">Visit history</button><button class="${attendanceTab==='inside'?'active':''}" data-action="attendance-tab" data-tab="inside">Currently inside · ${summary(state).inside}</button><button class="${attendanceTab==='refusals'?'active':''}" data-action="attendance-tab" data-tab="refusals">Refused entry · ${state.denials.length}</button></div><span class="badge gray">Gym-wide access</span></div>${attendanceTab==='refusals'?`<div class="table-wrap"><table><thead><tr><th>IDENTIFIER</th><th>REASON</th><th>DATE & TIME</th><th>RECORDED BY</th></tr></thead><tbody>${state.denials.slice().reverse().map(d=>`<tr><td>${esc(d.identifier)}</td><td>${badge(d.reason,'red')}</td><td>${dateFmt(d.at)} · ${timeFmt(d.at)}</td><td>${esc(d.actor)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No refused entry attempts in this demo session.</td></tr>'}</tbody></table></div>`:visitTable(attendanceTab==='inside'?visits.filter(v=>!v.checkedOut):visits.slice(0,35))}<div class="table-footer"><span>Staff photo confirmation is required before entry.</span><span>Attendance history is retained</span></div></section>`;}
function paymentTable(payments,own=false){return `<div class="table-wrap"><table><thead><tr><th>RECEIPT</th>${own?'':'<th>MEMBER</th>'}<th>PLAN</th><th>PAID</th><th>AMOUNT</th><th>METHOD</th><th></th></tr></thead><tbody>${payments.map(p=>{const m=state.members.find(m=>m.id===p.memberId),plan=state.plans.find(x=>x.id===p.planId);return `<tr><td>${esc(p.receipt)}</td>${own?'':`<td><strong>${esc(fullname(m))}</strong></td>`}<td>${esc(plan?.name)}</td><td>${dateFmt(p.paidAt,{day:'numeric',month:'short',year:'numeric'})}</td><td>${money(p.amount)}</td><td>${badge('Cash','gray')}</td><td><button class="btn text" data-action="receipt" data-id="${esc(p.id)}">View receipt</button></td></tr>`;}).join('')||`<tr><td colspan="7" class="empty">No payments found.</td></tr>`}</tbody></table></div>`;}
function payments(){const todays=state.payments.filter(p=>localDate(p.paidAt)===today());return intro('KEEP THE GOOD THINGS GOING','Membership payments','Cash receipts, clear records and a little less admin.',`<button class="btn primary" data-action="renew">${icon('plus')}Record renewal</button>`)+`<div class="receipt-summary"><div><small>Cash received today</small><strong>${money(todays.reduce((a,p)=>a+p.amount,0))}</strong></div><div><small>Receipts issued today</small><strong>${todays.length}</strong></div><div><small>Available plans</small><strong>${state.plans.filter(p=>p.available).length}</strong></div></div><section class="card table-card"><div class="card-head"><div><h2>Payment history</h2><p>Each confirmed cash payment carries a unique receipt.</p></div>${badge('Cash payments only','gray')}</div>${paymentTable(state.payments.slice().reverse())}<div class="table-footer"><span>All payment records are retained.</span><span>Plan and expiry derive from confirmed payments</span></div></section>`;}
function hoursCard(){const day=new Date(today()+'T12:00:00Z').getUTCDay();return `<section class="card"><div class="card-head"><div><h2>Opening hours</h2><p>Whole gym · normal weekly schedule</p></div>${role==='manager'?`<button class="icon-button" data-action="hours" aria-label="Edit opening hours">${icon('settings')}</button>`:''}</div><div class="hours-list">${Array.from({length:7},(_,i)=>{const d=(i+1)%7,h=state.hours.find(h=>h.scope==='gym'&&h.day===d);return `<div class="hours-row"><span>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d]} ${d===day?badge('Today','green'):''}</span><span>${!h||h.closed?'Closed':h.open+' – '+h.close}</span></div>`;}).join('')}<p style="font-size:10px;line-height:1.7;color:#a0ac91;margin-top:18px">A dated override takes priority over the normal schedule. Today: ${resolveHours(state,'gym').closed?'Closed':resolveHours(state,'gym').open+' – '+resolveHours(state,'gym').close}.</p></div></section>`;}
function noticesPage(publicView=false){const notices=role==='manager'&&!publicView?state.notices.slice().reverse().map(n=>({...n,status:n.cancelled?'Cancelled':n.ends<today()?'Ended':n.starts>today()?'Upcoming':'In effect'})):visibleNotices(state).sort((a,b)=>b.starts.localeCompare(a.starts));const actions=role==='manager'&&!publicView?`<button class="btn" data-action="hours">${icon('clock')}Edit hours</button><button class="btn primary" data-action="notice">${icon('plus')}Post notice</button>`:'';const gs=gymState();return intro(publicView?'SHOW UP FOR YOURSELF':'A HEADS-UP GOES A LONG WAY',publicView?'Your gym. Your next step.':'Notices & opening hours',publicView?'A quick look at what’s open and what’s coming up. No sign-in needed.':'Keep everyone informed, before they walk through the door.',actions)+`<div class="public-layout"><div>${publicView?`<section class="public-hero"><p class="eyebrow">${gs.open?'THE DOORS ARE OPEN':'MAKE TIME FOR YOUR NEXT VISIT'}</p><h2>${gs.open?'A little stronger, together.':'Your next session is waiting.'}</h2><p>Today’s gym hours: ${gs.hours.closed?'Closed':gs.hours.open+' – '+gs.hours.close}. All active memberships include gym-wide access.</p>${icon('gym')}</section>`:''}<div class="${notices.length>1?'two-cols':''}">${notices.map(n=>`<article class="card notice-full"><div style="display:flex;justify-content:space-between;gap:8px">${badge(n.status,n.status==='Upcoming'?'orange':n.status==='In effect'?'green':'gray')}${badge(scopeName(n.scope),'gray')}</div><h2>${esc(n.message)}</h2><p>${esc(n.detail||'Please speak to the front desk if you have questions.')}</p><footer><span>${dateFmt(n.starts)}${n.starts===n.ends?'':' – '+dateFmt(n.ends)}</span>${role==='manager'&&!n.cancelled&&!publicView?`<button class="btn text" data-action="cancel-notice" data-id="${esc(n.id)}">Cancel notice</button>`:''}</footer></article>`).join('')||`<section class="card empty">${icon('notice')}No current or upcoming notices. You’re all caught up.</section>`}</div><section class="card" style="margin-top:24px"><div class="card-head"><div><h2>Today across the gym</h2><p>Hours include any date-specific changes.</p></div>${badge(dateFmt(today(),{day:'numeric',month:'short'}),'gray')}</div><div class="card-body">${['gym','weights','cardio','studio'].map(scope=>{const h=resolveHours(state,scope);return `<div class="hours-row"><span>${scopeName(scope)}</span><span>${h.closed?badge('Closed today','red'):h.open+' – '+h.close}</span></div>`;}).join('')}</div></section></div>${hoursCard()}</div>`;}
function reportVisits(){return state.visits.filter(v=>reportDays===0||localDate(v.checkedIn)>=addDays(today(),-reportDays+1));}
function reports(){const vs=reportVisits(),unique=new Set(vs.map(v=>v.memberId)).size,plotDays=reportDays||Math.max(7,...vs.map(v=>daysBetween(localDate(v.checkedIn),today())+1));return intro('TURN ACTIVITY INTO UNDERSTANDING','Attendance reports','A clear view of the people and visits behind your gym’s progress.',`<select class="filter-select" id="report-range" aria-label="Report date range">${[[7,'Last 7 days'],[30,'Last 30 days'],[0,'All records']].map(([v,t])=>`<option value="${v}" ${reportDays===v?'selected':''}>${t}</option>`).join('')}</select><button class="btn" data-action="export-report">${icon('download')}Export CSV</button><button class="btn primary" data-action="print">${icon('print')}Print report</button>`)+`<div class="receipt-summary"><div><small>Total check-ins</small><strong>${vs.length}</strong></div><div><small>Unique members</small><strong>${unique}</strong></div><div><small>Completed visits</small><strong>${vs.filter(v=>v.checkedOut).length}</strong></div></div><section class="card report-chart"><div class="card-head"><div><h2>Daily attendance</h2><p>Visits across the selected reporting period.</p></div>${badge('Computed from attendance','gray')}</div><div class="chart-wrap">${attendanceChart(plotDays)}</div></section><section class="card table-card" style="margin-top:24px"><div class="card-head"><div><h2>Visits in this report</h2><p>Member identity photos are excluded from all reports.</p></div></div>${visitTable(vs.slice().reverse().slice(0,40),false)}<div class="table-footer"><span>Showing up to 40 visits. CSV includes all ${vs.length} matching records.</span><span>No separate report records are stored</span></div></section>`;}
function portal(){const m=state.members.find(m=>m.id===currentMember)||state.members[0],x=membership(state,m);const own=state.visits.filter(v=>v.memberId===m.id).slice().reverse().slice(0,5);return intro('MAKE A LITTLE TIME FOR YOU',`Good to see you, ${esc(m.first)}.`, 'Your membership, your progress and your next chance to show up.',`<label class="preview-select">Sample member<select id="sample-member">${state.members.map(m=>`<option value="${esc(m.id)}" ${currentMember===m.id?'selected':''}>${esc(fullname(m))}</option>`).join('')}</select></label>`)+`<div class="content-grid"><section class="membership-card"><p class="eyebrow">GYMFLOW MEMBERSHIP</p>${badge(m.account==='SUSPENDED'?'Account suspended':x.active?'Membership active':'Membership expired',x.active?'green':'orange')}<h2>${esc(x.plan?.name||'No plan')} membership</h2><p>Gym-wide access. A stronger routine starts here.</p><div class="membership-days"><strong>${x.days}</strong><span>days remaining</span></div><div class="member-info"><span>${esc(fullname(m))}</span><span>${esc(m.id)}</span><span>Expires ${dateFmt(x.expiry)}</span></div></section>${noticePreview()}</div>${m.account==='SUSPENDED'?'<div class="alert warning">Your account is suspended. Please speak to the front desk before your next visit.</div>':''}<div class="two-cols"><section class="card table-card"><div class="card-head"><div><h2>Your recent visits</h2><p>A little consistency adds up.</p></div></div>${visitTable(own,false)}</section><section class="card"><div class="card-head"><div><h2>Ready for your next chapter?</h2><p>Renewals are handled at the front desk.</p></div>${icon('gym')}</div><div class="card-body"><p style="font-size:12px;line-height:1.8;color:#91a07e">Choose a membership plan and pay cash at reception. Our staff will issue a receipt and show your updated expiry date.</p>${state.plans.filter(p=>p.available).map(p=>`<div class="hours-row"><span>${esc(p.name)} · ${p.days} days</span><strong>${money(p.price)}</strong></div>`).join('')}<button class="btn" data-action="nav" data-view="status" style="margin-top:18px">View gym hours ${icon('arrow')}</button></div></section></div>`;}
function auditPage(){return intro('A CLEAR RECORD OF EVERY CHANGE','Manager activity log','Notice and operating-hour changes are recorded with the actor and timestamp.')+`<section class="card">${state.audit.slice().reverse().map(a=>`<article class="audit-row"><div><strong>${esc(a.action)}</strong><span>${esc(a.entity)} · ${esc(a.actor)}</span></div><time>${dateFmt(a.at)} · ${timeFmt(a.at)}</time></article>`).join('')||'<div class="empty">No manager changes have been recorded.</div>'}</section>`;}
function renderPage(){return ({overview,members,attendance,payments,notices:()=>noticesPage(false),reports,audit:auditPage,portal,status:()=>noticesPage(true)}[view]||overview)();}

function openModal(title,sub,body,foot=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button type="button" class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!d.open)d.showModal();document.body.classList.add('modal-open');}
function closeModal(){const d=$('#modal');if(d.open)d.close();document.body.classList.remove('modal-open');}
function modalError(error){const el=$('#form-error');if(el){el.textContent=error.message||String(error);el.scrollIntoView({block:'nearest'});}else toast(error.message||String(error));}
function formBody(id,html,button){return `<form id="${id}"><div class="modal-body"><div id="form-error" class="inline-error" role="alert"></div>${html}</div><div class="modal-foot"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">${button}</button></div></form>`;}
const planOptions=()=>state.plans.filter(p=>p.available).map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${p.days} days · ${money(p.price)}</option>`).join('');
function paymentFields(){return `<div class="form-grid"><div class="field"><label for="plan-input">Membership plan *</label><select name="planId" id="plan-input" required>${planOptions()}</select></div><div class="field"><label for="receipt-input">Receipt number *</label><input id="receipt-input" name="receipt" value="DEMO-${String(Date.now()).slice(-7)}" required autocomplete="off"></div></div><div class="payment-total"><div><span>Cash payment due</span><small id="expiry-preview">Includes gym-wide access</small></div><strong id="plan-total">${money(state.plans.find(p=>p.available).price)}</strong></div><label class="checkbox"><input name="cashConfirmed" type="checkbox" required><span>I confirm this cash payment has been received.</span></label><div class="alert warning" style="margin-top:18px;margin-bottom:0">Demo calculation uses the revision’s proposed inclusive expiry rule. The final expiry and receipt-number policies require client confirmation.</div>`;}
function registerModal(){if(!staff())return;uploadedPhoto='';openModal('A fresh start. A new member.','Register identity details and the initial cash payment together.',formBody('register-form',`<p class="form-section first">Member details</p><div class="form-grid"><div class="field"><label for="first-input">First name *</label><input id="first-input" name="first" required autocomplete="off" placeholder="First name"></div><div class="field"><label for="last-input">Surname *</label><input id="last-input" name="last" required autocomplete="off" placeholder="Surname"></div><div class="field"><label for="idtype-input">ID type *</label><select name="idType" id="idtype-input"><option>Passport</option><option>National ID</option><option>Other approved ID</option></select></div><div class="field"><label for="idnumber-input">ID number *</label><input name="idNumber" id="idnumber-input" required placeholder="Use a fictional ID for this demo" autocomplete="off"></div><div class="field"><label for="photo-input">Identity photo *</label><input id="photo-input" type="file" accept="image/*" required><small>Demo photo, up to 2 MB. Photos appear only in staff identity verification.</small></div><div class="field"><label for="password-input">Member password *</label><input name="password" id="password-input" type="password" required autocomplete="new-password" placeholder="Demo password"><small>For the interface demonstration only. Use a sample password.</small></div></div><p class="form-section">Initial membership payment</p>${paymentFields()}`,'Register & issue receipt'));}
function renewModal(id){if(!staff())return;const m=state.members.find(m=>m.id===id)||state.members[0];openModal('Keep the momentum going.','Record a cash renewal and issue the member’s receipt.',formBody('renew-form',`<div class="field"><label for="renew-member">Member *</label><select id="renew-member" name="memberId">${state.members.map(x=>`<option value="${esc(x.id)}" ${m.id===x.id?'selected':''}>${esc(fullname(x))} · ${esc(x.id)}</option>`).join('')}</select></div><p class="form-section">Renew membership</p>${paymentFields()}`,'Record payment'));updatePaymentPreview();}
function updatePaymentPreview(){const sel=$('#plan-input');if(!sel)return;const plan=state.plans.find(p=>p.id===sel.value),m=state.members.find(m=>m.id===$('#renew-member')?.value),cur=m&&membership(state,m);$('#plan-total').textContent=money(plan.price);const expiry=cur?.active?addDays(cur.expiry,plan.days):addDays(today(),plan.days-1);$('#expiry-preview').textContent='New expiry: '+dateFmt(expiry)+(cur?.active?' · added to current expiry':'');}
function receiptModal(p,title='Payment recorded.'){const m=state.members.find(m=>m.id===p.memberId),plan=state.plans.find(x=>x.id===p.planId);openModal('Your next chapter starts here.','Cash receipt · '+esc(p.receipt),`<div class="modal-body"><div class="success-icon">${icon('check')}</div><h3 class="success-title">${esc(title)}</h3><p class="success-sub">${esc(fullname(m))} is all set for the next step.</p><div class="receipt-paper"><dl class="detail-list"><div><dt>Receipt number</dt><dd>${esc(p.receipt)}</dd></div><div><dt>Member</dt><dd>${esc(fullname(m))}</dd></div><div><dt>Membership</dt><dd>${esc(plan?.name)} · ${plan?.days} days</dd></div><div><dt>Cash received</dt><dd>${money(p.amount)}</dd></div><div><dt>New expiry date</dt><dd>${dateFmt(p.resultingExpiry)}</dd></div><div><dt>Received by</dt><dd>${esc(p.actor)}</dd></div><div><dt>Payment date</dt><dd>${dateFmt(p.paidAt)}</dd></div></dl></div></div>`,`<button class="btn" data-action="print">${icon('print')}Print receipt</button><button class="btn primary" data-action="close">Done ${icon('check')}</button>`);}
function memberModal(id){if(!staff())return;const m=state.members.find(m=>m.id===id);if(!m)return;const x=membership(state,m);openModal(esc(fullname(m)),esc(m.id)+' · Member overview',`<div class="modal-body"><div style="display:flex;gap:10px;align-items:center;margin-bottom:20px">${avatar(m,0,true)}${badge(x.active?'Membership active':'Membership expired',x.active?'green':'red')}${badge(m.account==='ENABLED'?'Account enabled':'Account suspended',m.account==='ENABLED'?'gray':'red')}</div><dl class="detail-list"><div><dt>Membership plan</dt><dd>${esc(x.plan?.name||'—')}</dd></div><div><dt>Current expiry</dt><dd>${dateFmt(x.expiry)}</dd></div><div><dt>Days remaining</dt><dd>${x.days}</dd></div><div><dt>Visits recorded</dt><dd>${state.visits.filter(v=>v.memberId===m.id).length}</dd></div><div><dt>Attendance</dt><dd>${openVisit(state,m.id)?'Currently in the gym':'Not checked in'}</dd></div><div><dt>Registered</dt><dd>${dateFmt(m.registeredAt)}</dd></div></dl></div>`,`<button class="btn" data-action="checkin-member" data-id="${esc(m.id)}">${icon('enter')}Check in</button><button class="btn primary" data-action="renew" data-id="${esc(m.id)}">Renew membership ${icon('arrow')}</button>`);}
function checkinModal(id=''){if(!staff())return;selectedCheckin=id;openModal('A little stronger with every visit.','Find the member, verify their identity and confirm entry.',`<div class="modal-body"><div id="form-error" class="inline-error" role="alert"></div><form id="lookup-form"><div class="field"><label for="checkin-search">Member number, ID or name</label><div style="display:flex;gap:8px"><input id="checkin-search" value="${esc(id)}" placeholder="Search for a member..." autocomplete="off"><button class="btn" type="submit">${icon('search')}Find</button></div></div></form><div id="checkin-result"></div></div><div class="modal-foot"><button class="btn" data-action="close">Cancel</button></div>`);if(id)showCheckinMember(id);else lookupMembers('');}
function lookupMembers(q){const list=state.members.filter(m=>(fullname(m)+' '+m.id+' '+m.idNumber).toLowerCase().includes(q.toLowerCase())).slice(0,5);$('#checkin-result').innerHTML=list.length?`<div class="checkin-results">${list.map((m,i)=>`<button class="result-member" data-action="select-checkin" data-id="${esc(m.id)}"><span class="name-cell">${avatar(m,i)}<span><strong>${esc(fullname(m))}</strong><small>${esc(m.id)}</small></span></span>${icon('arrow')}</button>`).join('')}</div>`:`<div class="alert error" style="margin-top:18px">No member matches “${esc(q)}”. An unknown-identifier refusal can be recorded below.</div><button class="btn danger" data-action="unknown-refusal" data-query="${esc(q)}">Record refused entry</button>`;}
function showCheckinMember(id){const m=state.members.find(m=>m.id===id);if(!m)return;selectedCheckin=id;const x=membership(state,m),reason=m.account!=='ENABLED'?'This member account is suspended.':!x.active?'This membership has expired.':openVisit(state,m.id)?'This member already has an open visit.':null;$('#checkin-result').innerHTML=`<div class="identity-card"><img src="${esc(m.photo)}" alt="Demo identity photograph for ${esc(fullname(m))}"><div><p class="eyebrow" style="margin:0">STAFF IDENTITY CHECK</p><h3>${esc(fullname(m))}</h3><p>${esc(m.id)} · ${esc(m.idType)} ${esc(m.idNumber)}</p>${badge(x.active?'Membership active':'Expired',x.active?'green':'red')}<p>${esc(x.plan?.name)} · expires ${dateFmt(x.expiry)}</p></div></div>${reason?`<div class="alert error">${esc(reason)} Entry cannot be confirmed.</div><button class="btn danger" data-action="blocked-refusal" data-id="${esc(id)}">Record refused entry</button>`:`<label class="checkbox"><input id="photo-confirm" type="checkbox"><span>I have matched the member in front of me to their protected identity photo.</span></label><p style="font-size:9px;color:#adb79b;line-height:1.7">This prototype uses sample identity photos. Live identity storage and sign-in are not connected.</p><div style="display:flex;gap:10px;margin-top:20px"><button class="btn danger" data-action="photo-refusal" data-id="${esc(id)}">Refuse entry</button><button class="btn primary" id="confirm-entry" data-action="confirm-entry" data-id="${esc(id)}" disabled>${icon('check')}Confirm check-in</button></div>`}`;}
function noticeModal(){if(role!=='manager'){toast('Only managers can post notices.');return;}openModal('A little heads-up for everyone.','Publish a notice for the gym or a specific area.',formBody('notice-form',`<div class="form-grid"><div class="field full"><label for="notice-title">Notice title *</label><input id="notice-title" name="message" required maxlength="140" placeholder="e.g. Studio maintenance"></div><div class="field full"><label for="notice-detail">Message</label><textarea id="notice-detail" name="detail" placeholder="What should members know?"></textarea></div><div class="field full"><label for="notice-scope">Applies to</label><select id="notice-scope" name="scope">${['gym','weights','cardio','studio'].map(s=>`<option value="${s}">${scopeName(s)}</option>`).join('')}</select></div><div class="field"><label for="notice-start">Starts on *</label><input type="date" id="notice-start" name="starts" value="${today()}" required></div><div class="field"><label for="notice-end">Ends on *</label><input type="date" id="notice-end" name="ends" value="${addDays(today(),7)}" required></div></div><div class="alert" style="margin-top:20px;margin-bottom:0">The notice is visible immediately after publication. Future dates appear as Upcoming; ended or cancelled notices disappear from public view.</div>`,'Publish notice'));}
function hoursModal(){if(role!=='manager'){toast('Only managers can change operating hours.');return;}const day=new Date(today()+'T12:00:00Z').getUTCDay(),h=resolveHours(state,'gym');openModal('Make time for the next session.','Update normal weekly hours or override one specific date.',formBody('hours-form',`<div class="form-grid"><div class="field"><label for="hours-scope">Applies to</label><select id="hours-scope" name="scope">${['gym','weights','cardio','studio'].map(s=>`<option value="${s}">${scopeName(s)}</option>`).join('')}</select></div><div class="field"><label for="hours-mode">Schedule type</label><select id="hours-mode" name="mode"><option value="weekly">Weekly schedule</option><option value="override">One-date override</option></select></div><div class="field full" id="weekday-field"><label for="hours-day">Weekday</label><select id="hours-day" name="day">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((t,i)=>`<option value="${i}" ${i===day?'selected':''}>${t}</option>`).join('')}</select></div><div class="field full" id="override-field" style="display:none"><label for="hours-date">Override date</label><input type="date" name="date" id="hours-date" value="${today()}"></div><div class="field"><label for="hours-open">Opens at</label><input id="hours-open" name="open" type="time" value="${h.open||'05:30'}"></div><div class="field"><label for="hours-close">Closes at</label><input id="hours-close" name="close" type="time" value="${h.close||'21:00'}"></div><label class="checkbox field full"><input type="checkbox" name="closed" id="hours-closed" ${h.closed?'checked':''}><span>Closed for this weekday or date</span></label></div><div class="alert" style="margin-top:20px;margin-bottom:0">An override affects only its named date. This change is recorded in the manager activity log.</div>`,'Save hours'));}
function updateHoursInputs(){const mode=$('#hours-mode').value,scope=$('#hours-scope').value,day=Number($('#hours-day').value),date=$('#hours-date').value||today();$('#weekday-field').style.display=mode==='weekly'?'':'none';$('#override-field').style.display=mode==='override'?'':'none';const h=mode==='weekly'?state.hours.find(h=>h.scope===scope&&h.day===day):resolveHours(state,scope,date);$('#hours-open').value=h?.open||'05:30';$('#hours-close').value=h?.close||'21:00';$('#hours-closed').checked=!!h?.closed;}
function previewModal(){openModal('Find your place in the gym.','Choose a role to explore the interface. These are demo workspaces, not production accounts.',`<div class="modal-body"><div class="demo-login">${[['staff','Front desk','Register members, take cash payments and confirm entry.'],['manager','Manager','All front-desk tools, plus notices, hours and the audit trail.'],['member','Member','View your plan, expiry date, days remaining and visits.'],['public','Public visitor','Check gym hours and current or upcoming notices.']].map(([r,t,d])=>`<button data-action="choose-role" data-role="${r}">${icon(r==='staff'?'users':r==='manager'?'shield':r==='member'?'card':'notice')} ${t}<small>${d}</small></button>`).join('')}</div><p style="font-size:10px;color:#a0ae8c;line-height:1.8;margin-top:20px">This prototype runs with sample records in your browser. It demonstrates the revised Gym Management System workflows.</p></div>`);}
function helpModal(){openModal('A little guide to the workspace.','Gym Management System · Software engineering project',`<div class="modal-body"><dl class="detail-list"><div><dt>Front desk</dt><dd>Members, cash payments and attendance</dd></div><div><dt>Manager</dt><dd>Notices, hours and change history</dd></div><div><dt>Member</dt><dd>Own membership and recent visits</dd></div><div><dt>Public visitor</dt><dd>Gym status without signing in</dd></div></dl><div class="alert warning" style="margin-top:20px">The interface is a working prototype with browser-local sample data. Production authentication, protected file storage and a shared database are not connected. Expiry and receipt policies remain proposed.</div><p style="font-size:11px;line-height:1.8;color:#8d9f77">Try the different roles using “Preview as”. Manager-only actions are also checked by the demo’s application logic. An active member with no open visit can be checked in after photo confirmation.</p><button class="btn danger" data-action="reset-demo">${icon('refresh')}Reset sample data</button></div>`,`<button class="btn primary" data-action="close">Got it ${icon('check')}</button>`);}
function downloadCSV(filename,rows){const csv='\uFEFF'+rows.map(row=>row.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);toast('CSV exported.');}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action,id=b.dataset.id;try{switch(a){
  case'nav':go(b.dataset.view);break;case'home':go(staff()?'overview':role==='member'?'portal':'status');break;
  case'menu':$('.sidebar').classList.toggle('open');break;case'close':closeModal();break;
  case'preview':previewModal();break;case'choose-role':setRole(b.dataset.role);break;case'help':helpModal();break;
  case'register':registerModal();break;case'renew':renewModal(id);break;case'member':memberModal(id);break;
  case'checkin':checkinModal();break;case'checkin-member':checkinModal(id);break;case'select-checkin':showCheckinMember(id);break;
  case'confirm-entry':{const r=attemptCheckIn(state,id,!!$('#photo-confirm')?.checked,role);persist();if(r.ok){closeModal();render();toast(fullname(r.member)+' checked in. Keep moving!');}else{showCheckinMember(id);toast('Entry refused: '+r.reason);}break;}
  case'blocked-refusal':case'photo-refusal':case'unknown-refusal':{const r=attemptCheckIn(state,a==='unknown-refusal'?b.dataset.query:id,false,role);persist();closeModal();render();toast(r.ok?'Checked in.':'Entry refusal recorded: '+r.reason);break;}
  case'checkout':{const v=checkOut(state,id,role),m=state.members.find(m=>m.id===v.memberId);persist();render();toast(fullname(m)+' checked out. See you next time.');break;}
  case'chart-range':chartDays=Number(b.dataset.days);render();break;case'attendance-tab':attendanceTab=b.dataset.tab;render();break;
  case'notice':noticeModal();break;case'cancel-notice':openModal('Cancel this notice?','It will disappear from the public status page. The manager action will be recorded.',`<div class="modal-body"><p style="font-size:12px;color:#8c9d77;line-height:1.8">${esc(state.notices.find(n=>n.id===id)?.message)}</p></div>`,`<button class="btn" data-action="close">Keep notice</button><button class="btn danger" data-action="confirm-cancel" data-id="${esc(id)}">Cancel notice</button>`);break;
  case'confirm-cancel':cancelNotice(state,id,role);persist();closeModal();render();toast('Notice cancelled. The change has been recorded.');break;
  case'hours':hoursModal();break;case'receipt':{const p=state.payments.find(p=>p.id===id);if(role==='member'&&p.memberId!==currentMember)throw new Error('This is not your receipt.');receiptModal(p,'Cash receipt');break;}
  case'print':window.print();break;
  case'export-report':{if(!staff())throw new Error('Staff access is required.');downloadCSV('gym-attendance-report.csv',[['Member number','Member','Check-in','Check-out','Confirmed by'],...reportVisits().map(v=>[v.memberId,fullname(state.members.find(m=>m.id===v.memberId)),v.checkedIn,v.checkedOut||'',v.confirmedBy])]);break;}
  case'export-members':{if(!staff())throw new Error('Staff access is required.');downloadCSV('gym-members.csv',[['Member number','Name','Plan','Expiry','Membership','Account'],...filteredMembers().map(m=>{const x=membership(state,m);return [m.id,fullname(m),x.plan?.name,x.expiry,x.active?'ACTIVE':'EXPIRED',m.account];})]);break;}
  case'reset-demo':openModal('Start fresh with the sample data?','This resets only the records in this browser.',`<div class="modal-body"><p style="font-size:12px;color:#8c9d77">Changes made during the demo will be replaced with the original sample records.</p></div>`,`<button class="btn" data-action="close">Keep my changes</button><button class="btn danger" data-action="confirm-reset">Reset demo</button>`);break;
  case'confirm-reset':state=seedState();currentMember=state.members[0].id;persist();closeModal();render();toast('Sample data restored.');break;
}}catch(err){modalError(err);}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.search){query=t.value;if(t.dataset.search==='global')view='members';const id=t.id,pos=t.selectionStart;render();const el=$('#'+id);el?.focus();el?.setSelectionRange(pos,pos);}if(t.id==='checkin-search')lookupMembers(t.value);});
document.addEventListener('change',e=>{const t=e.target;switch(t.id){case'role-preview':setRole(t.value);break;case'member-filter':memberFilter=t.value;render();break;case'report-range':reportDays=Number(t.value);render();break;case'sample-member':currentMember=t.value;render();break;case'plan-input':case'renew-member':updatePaymentPreview();break;case'photo-confirm':$('#confirm-entry').disabled=!t.checked;break;case'hours-mode':case'hours-scope':case'hours-day':case'hours-date':updateHoursInputs();break;case'photo-input':{uploadedPhoto='';const f=t.files[0];if(!f)return;if(!f.type.startsWith('image/')){t.value='';modalError(new Error('Choose an image file.'));return;}if(f.size>2*1024*1024){t.value='';modalError(new Error('Choose a demo image smaller than 2 MB.'));return;}const r=new FileReader();r.onload=()=>uploadedPhoto=r.result;r.readAsDataURL(f);break;}}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,form=Object.fromEntries(new FormData(f));try{if(f.id==='lookup-form'){const q=$('#checkin-search').value.trim();const exact=state.members.find(m=>m.id.toLowerCase()===q.toLowerCase()||m.idNumber.toLowerCase()===q.toLowerCase());if(exact)showCheckinMember(exact.id);else lookupMembers(q);return;}if(!f.checkValidity()){f.reportValidity();return;}switch(f.id){case'register-form':{if(!uploadedPhoto)throw new Error('Wait for the demo photo to load, or choose a photo.');const result=register(state,{...form,photo:uploadedPhoto,cashConfirmed:form.cashConfirmed==='on'},role);persist();render();receiptModal(result.payment,'Member registered.');break;}case'renew-form':{const p=renew(state,form.memberId,{...form,cashConfirmed:form.cashConfirmed==='on'},role);persist();render();receiptModal(p);break;}case'notice-form':publishNotice(state,form,role);persist();closeModal();render();toast('Notice published. Members can see it now.');break;case'hours-form':saveHours(state,{...form,closed:form.closed==='on'},role);persist();closeModal();render();toast('Hours updated. The manager change has been recorded.');break;}}catch(err){modalError(err);}});
$('#modal').addEventListener('close',()=>document.body.classList.remove('modal-open'));
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&staff()){e.preventDefault();$('#global-search')?.focus();}});
render();
